package org.novasos.healthysv2.patient;
import static org.novasos.healthysv2.patient.api.PatientDtos.*;
import java.util.*; import org.springframework.data.domain.Pageable; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.novasos.healthysv2.shared.api.dto.PageResponse; import org.novasos.healthysv2.shared.api.error.*;
@Service @Transactional class PatientService {
 private final PatientRepository patients;private final JdbcTemplate jdbc;PatientService(PatientRepository p,JdbcTemplate j){patients=p;jdbc=j;}
 PatientResponse create(PatientRequest r){require("identity.person",r.personId(),"Person");if(patients.existsByPersonId(r.personId()))throw new ConflictException("PERSON_ALREADY_PATIENT","error.patient.person.exists");return response(patients.save(Patient.create(r.personId(),r.bloodGroup(),r.rhesus(),r.maritalStatus(),r.occupation(),r.status())));}
 @Transactional(readOnly=true) PageResponse<PatientSummary> search(String q,Pageable pageable){return PageResponse.from(patients.search(q==null?"":q.trim(),pageable).map(this::summary));}@Transactional(readOnly=true) PatientResponse find(UUID id){return response(patient(id));}PatientResponse update(UUID id,PatientUpdateRequest r){var p=patient(id);p.update(r.bloodGroup(),r.rhesus(),r.maritalStatus(),r.occupation(),r.status());return response(p);}void delete(UUID id){patients.delete(patient(id));}
 IdentifierResponse addIdentifier(UUID p,IdentifierRequest r){var patient=patient(p);if(count("select count(*) from patient.patient_identifier where type=? and value=? and issuer is not distinct from ?",r.type().toUpperCase(),r.value(),blank(r.issuer()))>0)throw new ConflictException("PATIENT_IDENTIFIER_ALREADY_EXISTS","error.patient.identifier.exists");var x=patient.addIdentifier(r.type(),r.value(),r.issuer(),r.countryId(),r.expirationDate());patients.flush();return identifier(x);}IdentifierResponse updateIdentifier(UUID p,UUID id,IdentifierRequest r){var x=identifier(patient(p),id);x.update(r.type(),r.value(),r.issuer(),r.countryId(),r.expirationDate());return identifier(x);}void deleteIdentifier(UUID p,UUID id){var x=patient(p);x.remove(x.getIdentifiers(),identifier(x,id));}
 InsuranceResponse addInsurance(UUID p,InsuranceRequest r){require("catalog.insurance_company",r.insuranceCompanyId(),"InsuranceCompany");var patient=patient(p);var x=patient.addInsurance(r.insuranceCompanyId(),r.policyNumber(),r.memberNumber(),r.startDate(),r.endDate(),r.primary());patients.flush();return insurance(x);}InsuranceResponse updateInsurance(UUID p,UUID id,InsuranceRequest r){require("catalog.insurance_company",r.insuranceCompanyId(),"InsuranceCompany");var patient=patient(p);if(r.primary())patient.getInsurances().forEach(PatientInsurance::makeSecondary);var x=insurance(patient,id);x.update(r.insuranceCompanyId(),r.policyNumber(),r.memberNumber(),r.startDate(),r.endDate(),r.primary());return insurance(x);}void deleteInsurance(UUID p,UUID id){var x=patient(p);x.remove(x.getInsurances(),insurance(x,id));}
 RegistrationResponse addRegistration(UUID p,RegistrationRequest r){require("organization.organization",r.organizationId(),"Organization");var patient=patient(p);var x=patient.addRegistration(r.organizationId(),r.registrationNumber(),r.registeredAt(),r.status());patients.flush();return registration(x);}RegistrationResponse updateRegistration(UUID p,UUID id,RegistrationRequest r){require("organization.organization",r.organizationId(),"Organization");var x=registration(patient(p),id);x.update(r.organizationId(),r.registrationNumber(),r.registeredAt(),r.status());return registration(x);}void deleteRegistration(UUID p,UUID id){var x=patient(p);x.remove(x.getRegistrations(),registration(x,id));}
 AllergyResponse addAllergy(UUID p,AllergyRequest r){var patient=patient(p);var x=patient.addAllergy(r.allergen(),r.allergyType(),r.reaction(),r.severity(),r.status(),r.recordedAt(),r.recordedBy());patients.flush();return allergy(x);}AllergyResponse updateAllergy(UUID p,UUID id,AllergyRequest r){var x=allergy(patient(p),id);x.update(r.allergen(),r.allergyType(),r.reaction(),r.severity(),r.status(),r.recordedAt(),r.recordedBy());return allergy(x);}void deleteAllergy(UUID p,UUID id){var x=patient(p);x.remove(x.getAllergies(),allergy(x,id));}
 ChronicDiseaseResponse addChronicDisease(UUID p,ChronicDiseaseRequest r){var patient=patient(p);var x=patient.addChronicDisease(r.diagnosisCatalogId(),r.diagnosedAt(),r.status(),r.notes());patients.flush();return disease(x);}ChronicDiseaseResponse updateChronicDisease(UUID p,UUID id,ChronicDiseaseRequest r){var x=disease(patient(p),id);x.update(r.diagnosisCatalogId(),r.diagnosedAt(),r.status(),r.notes());return disease(x);}void deleteChronicDisease(UUID p,UUID id){var x=patient(p);x.remove(x.getChronicDiseases(),disease(x,id));}
 MedicalHistoryResponse addMedicalHistory(UUID p,MedicalHistoryRequest r){var patient=patient(p);var x=patient.addMedicalHistory(r.condition(),r.diagnosedAt(),r.resolvedAt(),r.notes());patients.flush();return medical(x);}MedicalHistoryResponse updateMedicalHistory(UUID p,UUID id,MedicalHistoryRequest r){var x=medical(patient(p),id);x.update(r.condition(),r.diagnosedAt(),r.resolvedAt(),r.notes());return medical(x);}void deleteMedicalHistory(UUID p,UUID id){var x=patient(p);x.remove(x.getMedicalHistories(),medical(x,id));}
 SurgicalHistoryResponse addSurgicalHistory(UUID p,SurgicalHistoryRequest r){if(r.organizationId()!=null)require("organization.organization",r.organizationId(),"Organization");var patient=patient(p);var x=patient.addSurgicalHistory(r.procedureName(),r.procedureDate(),r.organizationId(),r.notes());patients.flush();return surgical(x);}SurgicalHistoryResponse updateSurgicalHistory(UUID p,UUID id,SurgicalHistoryRequest r){if(r.organizationId()!=null)require("organization.organization",r.organizationId(),"Organization");var x=surgical(patient(p),id);x.update(r.procedureName(),r.procedureDate(),r.organizationId(),r.notes());return surgical(x);}void deleteSurgicalHistory(UUID p,UUID id){var x=patient(p);x.remove(x.getSurgicalHistories(),surgical(x,id));}
 FamilyHistoryResponse addFamilyHistory(UUID p,FamilyHistoryRequest r){var patient=patient(p);var x=patient.addFamilyHistory(r.relationship(),r.condition(),r.notes());patients.flush();return family(x);}FamilyHistoryResponse updateFamilyHistory(UUID p,UUID id,FamilyHistoryRequest r){var x=family(patient(p),id);x.update(r.relationship(),r.condition(),r.notes());return family(x);}void deleteFamilyHistory(UUID p,UUID id){var x=patient(p);x.remove(x.getFamilyHistories(),family(x,id));}
 DisabilityResponse addDisability(UUID p,DisabilityRequest r){var patient=patient(p);var x=patient.addDisability(r.type(),r.description(),r.startDate(),r.status());patients.flush();return disability(x);}DisabilityResponse updateDisability(UUID p,UUID id,DisabilityRequest r){var x=disability(patient(p),id);x.update(r.type(),r.description(),r.startDate(),r.status());return disability(x);}void deleteDisability(UUID p,UUID id){var x=patient(p);x.remove(x.getDisabilities(),disability(x,id));}
 NoteResponse addNote(UUID p,NoteRequest r){var patient=patient(p);var x=patient.addNote(r.authorPersonId(),r.noteType(),r.content(),null);patients.flush();return note(x);}NoteResponse updateNote(UUID p,UUID id,NoteRequest r){var x=note(patient(p),id);x.update(r.authorPersonId(),r.noteType(),r.content());return note(x);}void deleteNote(UUID p,UUID id){var x=patient(p);x.remove(x.getNotes(),note(x,id));}
 FlagResponse addFlag(UUID p,FlagRequest r){var patient=patient(p);var x=patient.addFlag(r.flagType(),r.label(),r.severity(),r.active(),null);patients.flush();return flag(x);}FlagResponse updateFlag(UUID p,UUID id,FlagRequest r){var x=flag(patient(p),id);x.update(r.flagType(),r.label(),r.severity(),r.active());return flag(x);}void deleteFlag(UUID p,UUID id){var x=patient(p);x.remove(x.getFlags(),flag(x,id));}
 EmergencyProfileResponse setEmergencyProfile(UUID p,EmergencyProfileRequest r){var patient=patient(p);var x=patient.setEmergencyProfile(r.emergencyCode(),r.bloodGroupVisible(),r.allergiesVisible(),r.conditionsVisible(),r.medicationsVisible(),r.emergencyContactVisible(),r.active());patients.flush();return emergency(x);}
 private Patient patient(UUID id){return patients.findById(id).orElseThrow(()->nf("Patient",id));}private void require(String table,UUID id,String resource){if(count("select count(*) from "+table+" where id=?",id)==0)throw nf(resource,id);}private int count(String sql,Object...args){return Objects.requireNonNull(jdbc.queryForObject(sql,Integer.class,args));}private String blank(String v){return v==null||v.isBlank()?null:v.trim();}private ResourceNotFoundException nf(String r,Object id){return new ResourceNotFoundException(r,id);}
 private PatientIdentifier identifier(Patient p,UUID id){return p.getIdentifiers().stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->nf("PatientIdentifier",id));}private PatientInsurance insurance(Patient p,UUID id){return p.getInsurances().stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->nf("PatientInsurance",id));}private PatientRegistration registration(Patient p,UUID id){return p.getRegistrations().stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->nf("PatientRegistration",id));}private Allergy allergy(Patient p,UUID id){return p.getAllergies().stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->nf("Allergy",id));}private ChronicDisease disease(Patient p,UUID id){return p.getChronicDiseases().stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->nf("ChronicDisease",id));}private MedicalHistory medical(Patient p,UUID id){return p.getMedicalHistories().stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->nf("MedicalHistory",id));}private SurgicalHistory surgical(Patient p,UUID id){return p.getSurgicalHistories().stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->nf("SurgicalHistory",id));}private FamilyHistory family(Patient p,UUID id){return p.getFamilyHistories().stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->nf("FamilyHistory",id));}private Disability disability(Patient p,UUID id){return p.getDisabilities().stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->nf("Disability",id));}private PatientNote note(Patient p,UUID id){return p.getNotes().stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->nf("PatientNote",id));}private PatientFlag flag(Patient p,UUID id){return p.getFlags().stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->nf("PatientFlag",id));}
 private PatientSummary summary(Patient p){return new PatientSummary(p.getId(),p.getPersonId(),p.getPatientNumber(),p.getBloodGroup(),p.getRhesus(),p.getStatus());}private PatientResponse response(Patient p){return new PatientResponse(p.getId(),p.getPersonId(),p.getPatientNumber(),p.getBloodGroup(),p.getRhesus(),p.getMaritalStatus(),p.getOccupation(),p.getStatus(),p.getCreatedAt(),p.getUpdatedAt(),p.getIdentifiers().stream().map(this::identifier).toList(),p.getInsurances().stream().map(this::insurance).toList(),p.getRegistrations().stream().map(this::registration).toList(),p.getAllergies().stream().map(this::allergy).toList(),p.getChronicDiseases().stream().map(this::disease).toList(),p.getMedicalHistories().stream().map(this::medical).toList(),p.getSurgicalHistories().stream().map(this::surgical).toList(),p.getFamilyHistories().stream().map(this::family).toList(),p.getDisabilities().stream().map(this::disability).toList(),p.getNotes().stream().map(this::note).toList(),p.getFlags().stream().map(this::flag).toList(),p.getEmergencyProfile()==null?null:emergency(p.getEmergencyProfile()));}
 private IdentifierResponse identifier(PatientIdentifier x){return new IdentifierResponse(x.getId(),x.getType(),x.getValue(),x.getIssuer(),x.getCountryId(),x.getExpirationDate());}private InsuranceResponse insurance(PatientInsurance x){return new InsuranceResponse(x.getId(),x.getInsuranceCompanyId(),x.getPolicyNumber(),x.getMemberNumber(),x.getStartDate(),x.getEndDate(),x.isPrimary());}private RegistrationResponse registration(PatientRegistration x){return new RegistrationResponse(x.getId(),x.getOrganizationId(),x.getRegistrationNumber(),x.getRegisteredAt(),x.getStatus());}private AllergyResponse allergy(Allergy x){return new AllergyResponse(x.getId(),x.getAllergen(),x.getType(),x.getReaction(),x.getSeverity(),x.getStatus(),x.getRecordedAt(),x.getRecordedBy());}private ChronicDiseaseResponse disease(ChronicDisease x){return new ChronicDiseaseResponse(x.getId(),x.getDiagnosisCatalogId(),x.getDiagnosedAt(),x.getStatus(),x.getNotes());}private MedicalHistoryResponse medical(MedicalHistory x){return new MedicalHistoryResponse(x.getId(),x.getCondition(),x.getDiagnosedAt(),x.getResolvedAt(),x.getNotes());}private SurgicalHistoryResponse surgical(SurgicalHistory x){return new SurgicalHistoryResponse(x.getId(),x.getProcedureName(),x.getProcedureDate(),x.getOrganizationId(),x.getNotes());}private FamilyHistoryResponse family(FamilyHistory x){return new FamilyHistoryResponse(x.getId(),x.getRelationship(),x.getCondition(),x.getNotes());}private DisabilityResponse disability(Disability x){return new DisabilityResponse(x.getId(),x.getType(),x.getDescription(),x.getStartDate(),x.getStatus());}private NoteResponse note(PatientNote x){return new NoteResponse(x.getId(),x.getAuthorPersonId(),x.getType(),x.getContent(),x.getCreatedAt());}private FlagResponse flag(PatientFlag x){return new FlagResponse(x.getId(),x.getType(),x.getLabel(),x.getSeverity(),x.isActive(),x.getCreatedAt());}private EmergencyProfileResponse emergency(EmergencyProfile x){return new EmergencyProfileResponse(x.getId(),x.getEmergencyCode(),x.isBloodGroupVisible(),x.isAllergiesVisible(),x.isConditionsVisible(),x.isMedicationsVisible(),x.isEmergencyContactVisible(),x.isActive());}
}
